  const groups = paren_string.trim().split(/\s+/);
  const result = groups.map(group => {
    let maxDepth = 0;
    let currentDepth = 0;
    for (const char of group) {
      if (char === '(') {
        currentDepth++;
        if (currentDepth > maxDepth) maxDepth = currentDepth;
      } else if (char === ')') {
        currentDepth = Math.max(0, currentDepth - 1);
      }
    }
    return maxDepth;
  });
  return result;
};

